package com.foodbridge.listing;
import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.io.*;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
@Controller public class BulkListingController {private final RetailListingRepository repo;public BulkListingController(RetailListingRepository r){repo=r;}
    @GetMapping("/staff/listings/bulk") public String form(){return "listing/bulk";}
    @PostMapping("/staff/listings/bulk") public String upload(@RequestParam("file") MultipartFile file,Model model){int created=0,duplicates=0,invalid=0;List<String> errors=new ArrayList<>();if(file.isEmpty()){model.addAttribute("error","Choose a CSV file first.");return "listing/bulk";}
        try(BufferedReader br=new BufferedReader(new InputStreamReader(file.getInputStream(),java.nio.charset.StandardCharsets.UTF_8))){String line;int row=0;while((line=br.readLine())!=null){row++;if(row==1&&line.toLowerCase(Locale.ROOT).contains("name")&&line.toLowerCase(Locale.ROOT).contains("saleprice"))continue;try{String[] c=line.split(",",-1);if(c.length!=7)throw new IllegalArgumentException("Expected 7 comma-separated columns");String name=c[0].trim(),desc=c[1].trim(),location=c[5].trim();BigDecimal original=new BigDecimal(c[2].trim()),sale=new BigDecimal(c[3].trim());int qty=Integer.parseInt(c[4].trim());LocalDateTime cutoff=LocalDateTime.parse(c[6].trim());if(name.isBlank()||location.isBlank()||original.signum()<=0||sale.signum()<=0||sale.compareTo(original)>0||qty<1||cutoff.isBefore(LocalDateTime.now()))throw new IllegalArgumentException("Invalid product fields, prices, quantity, or cutoff");boolean dup=repo.findAll().stream().anyMatch(x->x.getName().equalsIgnoreCase(name)&&x.getPickupLocation().equalsIgnoreCase(location)&&x.getSafetyCutoff().equals(cutoff));if(dup){duplicates++;continue;}repo.save(new RetailListing(name,desc,original,sale,qty,location,cutoff,true));created++;}catch(Exception e){invalid++;errors.add("Row "+row+": "+e.getMessage());}}}catch(IOException e){model.addAttribute("error","Unable to read uploaded CSV.");return "listing/bulk";}model.addAttribute("created",created);model.addAttribute("duplicates",duplicates);model.addAttribute("invalid",invalid);model.addAttribute("errors",errors);return "listing/bulk-result";}
}
